"use client";

import "./tooltip.css";

import {
  cloneElement,
  isValidElement,
  useId,
  useState,
  type ComponentProps,
  type ReactElement,
  type ReactNode,
} from "react";
import { cx } from "./cx";

export type TooltipProps = Omit<ComponentProps<"span">, "content"> & {
  content: ReactNode;
};

function describedBy(...parts: Array<string | undefined>) {
  const value = parts.filter(Boolean).join(" ");
  return value || undefined;
}

export function Tooltip({
  content,
  className,
  children,
  onKeyDown,
  onBlur,
  onMouseLeave,
  ...rest
}: TooltipProps) {
  const tipId = useId();
  const [dismissed, setDismissed] = useState(false);
  const triggerDescribedBy = isValidElement(children)
    ? describedBy(
        (children.props as { "aria-describedby"?: string })["aria-describedby"],
        tipId,
      )
    : tipId;
  const trigger = isValidElement(children)
    ? cloneElement(
        children as ReactElement<{ "aria-describedby"?: string }>,
        triggerDescribedBy
          ? { "aria-describedby": triggerDescribedBy }
          : {},
      )
    : (
        <span tabIndex={0} aria-describedby={tipId}>
          {children}
        </span>
      );

  return (
    <span
      className={cx("ns-tooltip", className)}
      data-dismissed={dismissed ? "" : undefined}
      onKeyDown={(event) => {
        if (event.key === "Escape") setDismissed(true);
        onKeyDown?.(event);
      }}
      onBlur={(event) => {
        setDismissed(false);
        onBlur?.(event);
      }}
      onMouseLeave={(event) => {
        setDismissed(false);
        onMouseLeave?.(event);
      }}
      {...rest}
    >
      {trigger}
      <span className="ns-tooltip__tip" id={tipId} role="tooltip">
        {content}
      </span>
    </span>
  );
}

@layer components {
  .ns-tooltip {
    position: relative;
    display: inline-flex;
  }

  .ns-tooltip__tip {
    position: absolute;
    inset-block-start: calc(100% + var(--space-2, 0.31rem));
    left: 50%;
    z-index: var(--z-overlay, 20);
    width: max-content;
    max-width: 14rem;
    padding: var(--space-2, 0.31rem) var(--space-3, 0.39rem);
    border: 1px solid
      var(--line, color-mix(in srgb, var(--text-heading, #111) 18%, transparent));
    border-radius: var(--radius, 0.4rem);
    background: var(--bg-overlay, var(--bg, #fff));
    color: var(--text-body, #444);
    font-size: var(--type-sm, 0.8rem);
    line-height: var(--leading-tight, 1.25);
    opacity: 0;
    pointer-events: none;
    translate: -50% 0;
    transition: opacity var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1))
      0.4s;
  }

  .ns-tooltip:hover .ns-tooltip__tip,
  .ns-tooltip:focus-within .ns-tooltip__tip {
    opacity: 1;
  }

  .ns-tooltip[data-dismissed] .ns-tooltip__tip,
  .ns-tooltip[data-dismissed]:hover .ns-tooltip__tip,
  .ns-tooltip[data-dismissed]:focus-within .ns-tooltip__tip {
    opacity: 0;
    transition: none;
  }

  @media (prefers-reduced-motion: reduce) {
    .ns-tooltip__tip {
      transition: none;
    }
  }
}
